INSERT INTO MERIDIAN.CORE.LISTINGS (LISTING_ID, NAME, PUBLISHER, CATEGORY, FEATURED, CONSUMER, INSTALLS, WEEKLY_ACTIVE_PCT, EVAL_PCT, P95_MS, SOC2, DATA_REFRESHED_ON, FRESHNESS_RULE_DAYS, PRICE_MODEL, DESCRIPTION, KEYWORDS) VALUES
  ('orbit', 'GTM Orbit', 'Orbit Labs', 'Prospecting', 1, 0, 1284, 71, 96.4, 1800, 'Type II', NULL, NULL, 'Usage or annual private offer', 'Account research, buying signals and first-touch outreach for B2B sellers.', 'account research prospect outreach pipeline buying signal sales crm brief call prep'),
  ('conviction', 'Conviction AI', 'Conviction Labs', 'Investing', 1, 0, 612, 66, 94.8, 3600, 'Type II', NULL, NULL, 'Per seat, annual', 'Investment intelligence for VC and PE firms: cited diligence memos, portfolio monitoring and add-on screening.', 'investment intelligence diligence memo venture private equity vc pe portfolio add-on'),
  ('credits', 'Credit Simulator', 'Credit Simulator', 'Pricing', 1, 0, 214, 79, 97.1, 4200, 'Type II', NULL, NULL, 'Annual, per workspace', 'Simulates moving a seat-based plan to credits using billing and usage history.', 'pricing credits usage based seat migration simulation monetization billing'),
  ('readaroo', 'Readaroo', 'Readaroo', 'Consumer', 1, 1, 48200, 58, 95.2, 1100, 'Type II', NULL, NULL, 'Free; fines paid to libraries', 'An online library: one shelf across library cards, read-tonight search, kid-safe family shelves.', 'library books ebook audiobook borrow reading kids family'),
  ('fieldwise', 'Fieldwise', 'Fieldwise', 'Field service', 1, 0, 386, 74, 96.0, 1400, 'Type II', NULL, NULL, 'Per technician, annual', 'Guided field-service resolution: confirms the exact model before any step, cites the manual page, and hands a reviewer-approved procedure to the technician''s phone.', 'field service repair fault code technician service desk elevator equipment first-time fix manual procedure troubleshooting dispatch'),
  ('purlwise', 'Purlwise', 'Purlwise', 'Hobbies', 0, 1, 31800, 63, 93.0, 900, 'Type II', NULL, NULL, 'Free with paid patterns', 'Knit and crochet patterns searchable by the yarn you own, resized to your gauge, with a row counter.', 'knit knitting crochet pattern yarn gauge row counter craft'),
  ('washbloom', 'Wash & Bloom', 'Wash & Bloom', 'Hobbies', 0, 1, 9700, 47, 91.5, 1300, 'Type II', NULL, NULL, 'Free', 'Daily watercolor prompts, mixing recipes from your paints, and feedback on a photo of your piece.', 'watercolor painting palette mixing art'),
  ('callsight', 'Callsight', 'Callsight', 'Conversation intelligence', 0, 0, 2940, 74, 95.5, 2100, 'Type II', NULL, NULL, 'Per seat', 'Summarizes sales calls, flags competitor and risk language, suggests one coaching moment per call.', 'conversation intelligence call summary coaching competitor objection'),
  ('dealnote', 'Dealnote', 'Dealnote', 'Deal execution', 0, 0, 1870, 69, 94.1, 1900, 'Type II', NULL, NULL, 'Per seat', 'Turns calls and emails into MEDDICC deal notes, next steps and risks on the opportunity.', 'deal notes meddicc qualification next steps crm'),
  ('quotacraft', 'Quotacraft', 'Quotacraft', 'Planning', 0, 0, 540, 61, 92.8, 2600, 'Type II', NULL, NULL, 'Annual', 'Quota and territory planning from ramp and attrition, with quota letters ready for finance.', 'quota planning territory capacity headcount ramp'),
  ('forecastpulse', 'Forecast Pulse', 'Pulse Analytics', 'Forecasting', 0, 0, 1310, 72, 94.6, 2300, 'Type II', NULL, NULL, 'Per seat', 'Rolls up the weekly forecast and explains every gap between commits and deal evidence.', 'forecast commit roll up coverage'),
  ('fieldnote', 'Fieldnote Firmographics', 'Fieldnote Data', 'Data', 0, 0, 3410, 64, 97.9, 600, 'Type II', '2026-09-24', 30, 'Per call', 'Company size, funding, tech stack and hiring signals. Agents call it as a tool.', 'firmographic company data enrichment hiring funding'),
  ('pipehealth', 'Pipeline Steward', 'Steward Ops', 'RevOps', 0, 0, 2050, 63, 93.3, 1700, 'Type II', NULL, NULL, 'Usage', 'Finds stale opportunities and duplicates and proposes fixes in one approval batch.', 'revops crm hygiene data quality pipeline duplicates'),
  ('icpscout', 'ICP Scout', 'Scout Data', 'Prospecting', 0, 0, 980, 57, 91.2, 1500, 'Not provided', NULL, NULL, 'Usage', 'Scores accounts against your ideal customer profile with the top three reasons.', 'icp account scoring targeting segmentation'),
  ('winloss', 'Win-Loss Lens', 'Lens Research', 'Conversation intelligence', 0, 0, 760, 41, 92.0, 2800, 'Type II', NULL, NULL, 'Annual', 'Interviews won and lost buyers by email and trends the reasons by segment.', 'win loss analysis competitor interviews'),
  ('renewal', 'Renewal Radar', 'Radar CS', 'Customer success', 0, 0, 1450, 67, 94.0, 1600, 'Type II', NULL, NULL, 'Per seat', 'Flags renewals at risk from usage drops and drafts a save plan.', 'renewal churn retention expansion'),
  ('rampcoach', 'Ramp Coach', 'Ramp', 'Enablement', 0, 0, 1120, 49, 92.4, 2000, 'Type II', NULL, NULL, 'Per seat', '30-60-90 plans for new reps with quizzes on real calls.', 'enablement onboarding ramp coaching'),
  ('pricewell', 'Pricewell', 'Pricewell', 'Deal execution', 0, 0, 940, 55, 97.8, 1200, 'Type II', NULL, NULL, 'Usage + annual', 'Builds quotes within discount guardrails and explains exceptions to deal desk.', 'quote cpq pricing discount deal desk'),
  ('cosell', 'Co-sell Map', 'Overlap Labs', 'Partnerships', 0, 0, 690, 52, 93.7, 1400, 'Type II', NULL, NULL, 'Annual', 'Finds account overlap with partners and suggests co-sell plays without sharing raw lists.', 'partner co-sell overlap alliances'),
  ('launchpilot', 'Launch Pilot', 'Pilot GTM', 'Enablement', 0, 0, 2875, 36, 90.9, 2200, 'Type II', NULL, NULL, 'Per seat', 'Turns a launch brief into talk tracks and battlecards and tracks use on calls.', 'product launch battlecard talk track');
